/// Returns `true` iff `a` is sorted in nondecreasing order.
///
/// Nondecreasing means: for all i < j, a[i] <= a[j].
/// With a non-empty slice, this is equivalent to: for every adjacent pair,
/// a[k] <= a[k + 1]. If any adjacent inversion exists, the array is not sorted.
pub fn is_sorted(a: &[i32]) -> bool {
    // Input is guaranteed non-empty, but this also works for empty.
    a.windows(2).all(|w| w[0] <= w[1])
}

